class ContextualPromptBuilderTest {

    @Test
    fun build_withLatestDetection_injectsDiseaseConfidenceUrgensiAndNotes() {
        val detection = DetectionHistoryEntity(
            id = 1,
            username = "yusuf",
            kelas = "Gingivitis",
            confidence = 0.875f,
            urgensi = "KONTROL_RUTIN",
            deskripsi = "Radang gusi",
            catatanKeluhan = "Gusi berdarah saat sikat"
        )

        val payload = ContextualPromptBuilder.build(detection, "Apa perawatan awalnya?")
        val systemInstruction = payload.systemInstruction

        assertTrue(systemInstruction.contains("Gingivitis"))
        assertTrue(systemInstruction.contains("87.5%"))
        assertTrue(systemInstruction.contains("KONTROL_RUTIN"))
        assertTrue(systemInstruction.contains("Gusi berdarah saat sikat"))
        assertTrue(systemInstruction.contains("Sensodyne") || systemInstruction.contains("Pepsodent"))
        assertTrue(systemInstruction.contains(ContextualPromptBuilder.DISCLAIMER_KEYWORD))
    }

