    @Test
    fun classifyResponseStyle_adaptsBetweenGreetingShortAndDetailedQuestions() {
        assertEquals(
            ResponseLengthStyle.GREETING,
            ContextualPromptBuilder.classifyResponseStyle("halo")
        )
        assertEquals(
            ResponseLengthStyle.GREETING,
            ContextualPromptBuilder.classifyResponseStyle("Selamat pagi dok")
        )
        assertEquals(
            ResponseLengthStyle.SHORT_SIMPLE,
            ContextualPromptBuilder.classifyResponseStyle("Boleh sikat gigi habis makan?")
        )
        assertEquals(
            ResponseLengthStyle.DETAILED,
            ContextualPromptBuilder.classifyResponseStyle(
                "Gigi geraham belakang saya terasa ngilu tiap minum dingin sejak seminggu lalu, apa saja penyebabnya dan langkah perawatan harian yang bisa saya lakukan?"
            )
        )
    }

    @Test
    fun build_followUpTurn_forbidsRepetitiveHaloAndExcessiveQuestionsAndAllowsSparseEmoji() {
        val payload = ContextualPromptBuilder.build(
            latestDetection = null,
            userQuestion = "Kalau obat kumur dipakai kapan?",
            isFirstTurn = false
        )
        val instruction = payload.systemInstruction

        assertTrue(instruction.contains("DILARANG") && instruction.contains("Halo"))
        assertTrue(instruction.contains("emoji", ignoreCase = true))
        assertTrue(instruction.contains("jangan terlalu sering bertanya", ignoreCase = true) || instruction.contains("tidak perlu selalu mengakhiri dengan pertanyaan", ignoreCase = true))
        assertTrue(instruction.contains("tidak perlu", ignoreCase = true) && instruction.contains("disclaimer", ignoreCase = true))
    }

    @Test
    fun isSensitiveMedicalQuery_detectsSevereSymptomsPrescriptionsAndVulnerableGroups() {
        assertTrue(ContextualPromptBuilder.isSensitiveMedicalQuery("Pipi saya bengkak keluar nanah dan demam, boleh minum amoxicillin?"))
        assertTrue(ContextualPromptBuilder.isSensitiveMedicalQuery("Saya sedang hamil 6 bulan dan sakit gigi hebat, obat apa yang aman?"))
        assertTrue(ContextualPromptBuilder.isSensitiveMedicalQuery("Sariawan saya sudah 3 minggu tidak sembuh dan ada benjolan keras"))
        assertFalse(ContextualPromptBuilder.isSensitiveMedicalQuery("Boleh sikat gigi dua kali sehari?"))
        assertFalse(ContextualPromptBuilder.isSensitiveMedicalQuery("halo"))
    }

    @Test
    fun build_sensitiveMedicalQuery_enforcesInitialReferenceBoundaryAndDoctorReferral() {
        val payload = ContextualPromptBuilder.build(
            latestDetection = null,
            userQuestion = "Gusi bengkak sampai pipi, bernanah, dan demam. Minta resep antibiotik dong dok.",
            isFirstTurn = true
        )
        val instruction = payload.systemInstruction

        assertTrue(instruction.contains("PERTANYAAN MEDIS SENSITIF"))
        assertTrue(instruction.contains("pengetahuan awal") || instruction.contains("referensi awal"))
        assertTrue(instruction.contains("dokter gigi") || instruction.contains("ahli"))
        assertTrue(instruction.contains("resep") || instruction.contains("antibiotik"))
    }

    @Test
    fun assessCaseSeverity_detectsSevereSymptomsAndHighUrgencyScan() {
        val severeByText = ContextualPromptBuilder.assessCaseSeverity(
            userQuestion = "Pipi saya bengkak parah dan keluar nanah disertai demam",
            latestDetection = null
        )
        assertEquals(CaseSeverity.SEVERE_URGENT, severeByText.severity)
        assertTrue(severeByText.matchedIndicators.contains("bengkak"))
        assertTrue(severeByText.reasonSummary?.contains("dokter gigi") == true)

        val urgentScan = DetectionHistoryEntity(
            id = 9,
            username = "guest",
            kelas = "Caries",
            confidence = 0.92f,
            urgensi = "SEGERA_KE_DOKTER",
            deskripsi = "Karies berat",
            catatanKeluhan = ""
        )
        val severeByScan = ContextualPromptBuilder.assessCaseSeverity(
            userQuestion = "Apa yang harus saya lakukan?",
            latestDetection = urgentScan
        )
        assertEquals(CaseSeverity.SEVERE_URGENT, severeByScan.severity)

        val normal = ContextualPromptBuilder.assessCaseSeverity(
            userQuestion = "Berapa kali sehari sebaiknya menyikat gigi?",
            latestDetection = null
        )
        assertEquals(CaseSeverity.NORMAL, normal.severity)
    }

